import { Component, OnInit, inject, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { ApplicationService, QuizAnswerPayload } from '../../../core/services/application.service';
import { QuizService } from '../../../core/services/quiz.service';
import { environment } from '../../../../environments/environment';
import { QuizPlayerComponent } from '../../../shared/components/quiz-player/quiz-player.component';

@Component({
  selector: 'app-job-search',
  standalone: true,
  imports: [CommonModule, FormsModule, QuizPlayerComponent],
  templateUrl: './job-search.component.html',
  styleUrls: ['./job-search.component.css'],
})
export class JobSearchComponent implements OnInit {
  readonly environment = environment;
  private cdr = inject(ChangeDetectorRef);
  private router = inject(Router);
  private http = inject(HttpClient);
  private applicationService = inject(ApplicationService);
  private quizService = inject(QuizService);

  allJobs: any[] = [];
  isLoading = true;
  selectedJob: any = null;
  selectedRecruiter: any = null;

  showConfirmApplyPopup = false;
  applyPopupSuccess = false;
  jobToApply: any = null;
  showAuthRequiredPopup = false;

  jobQuiz: any = null;
  quizAnswers: Record<number, number> = {};
  isLoadingQuiz = false;
  applyError = '';
  isSubmitting = false;

  searchFilters = { title: '', location: '', experience: '', contract: '' };
  isLoggedIn = false;

  ngOnInit() {
    this.isLoggedIn = !!localStorage.getItem('token');
    this.fetchAvailableJobs();
  }

  fetchAvailableJobs() {
    const token = localStorage.getItem('token');

    const jobsPromise = this.http
      .get<any>(`${environment.apiUrl}/candidate/jobs/list`)
      .toPromise();

    let historyPromise: Promise<any> = Promise.resolve({ history: [] });
    if (token) {
      historyPromise = this.applicationService
        .getHistory()
        .toPromise()
        .catch(() => ({ history: [] }));
    }

    Promise.all([jobsPromise, historyPromise])
      .then(([jobsData, historyData]) => {
        const jobsList = Array.isArray(jobsData) ? jobsData : jobsData?.jobs || [];
        const historyList = historyData?.history || [];
        const appliedJobIds = historyList.map((app: any) => app.job_id);

        this.allJobs = jobsList.map((job: any) => ({
          ...job,
          has_quiz: !!job.has_quiz,
          isAlreadyApplied: token ? appliedJobIds.includes(job.id) : false,
        }));
        this.isLoading = false;
        this.cdr.detectChanges();
      })
      .catch(() => {
        this.isLoading = false;
        this.cdr.detectChanges();
      });
  }

  loadQuizForJob(jobId: number) {
    const token = localStorage.getItem('token');
    this.isLoadingQuiz = true;
    this.jobQuiz = null;
    this.quizAnswers = {};
    this.quizService.getQuizForJob(jobId, !token).subscribe({
      next: (res) => {
        this.jobQuiz = res.has_quiz ? res.quiz : null;
        this.isLoadingQuiz = false;
        this.cdr.detectChanges();
      },
      error: () => {
        this.isLoadingQuiz = false;
        this.jobQuiz = null;
        this.cdr.detectChanges();
      },
    });
  }

  onViewRecruiterProfile(recruiterId: number) {
    if (!recruiterId) return;
    this.http
      .get(`${environment.apiUrl}/candidate/profile/details-public/${recruiterId}`)
      .subscribe({
        next: (data) => {
          this.selectedRecruiter = data;
          this.cdr.detectChanges();
        },
        error: () => alert("Impossible de charger la fiche de cette entreprise."),
      });
  }

  getSearchJobSkillsArray(skillsText: string): string[] {
    if (!skillsText) return [];
    return skillsText.split(',').map((s) => s.trim()).filter(Boolean);
  }

  getSearchJobLanguagesArray(langText: string): string[] {
    if (!langText) return [];
    return langText.split(',').map((s) => s.trim()).filter(Boolean);
  }

  onCloseRecruiterModal() {
    this.selectedRecruiter = null;
    this.cdr.detectChanges();
  }

  get filteredJobs() {
    return this.allJobs.filter((job) => {
      const matchTitle =
        !this.searchFilters.title.trim() ||
        job.title?.toLowerCase().includes(this.searchFilters.title.toLowerCase()) ||
        job.company_name?.toLowerCase().includes(this.searchFilters.title.toLowerCase());
      const matchLocation =
        !this.searchFilters.location.trim() ||
        job.location?.toLowerCase().includes(this.searchFilters.location.toLowerCase());
      const matchExperience =
        !this.searchFilters.experience || job.experience_level === this.searchFilters.experience;
      const matchContract =
        !this.searchFilters.contract || job.contract_type === this.searchFilters.contract;
      return matchTitle && matchLocation && matchExperience && matchContract;
    });
  }

  get hasActiveFilters(): boolean {
    return !!(
      this.searchFilters.title.trim() ||
      this.searchFilters.location.trim() ||
      this.searchFilters.experience ||
      this.searchFilters.contract
    );
  }

  onResetFilters() {
    this.searchFilters = { title: '', location: '', experience: '', contract: '' };
    this.cdr.detectChanges();
  }

  onViewJobDetails(job: any) {
    this.selectedJob = job;
    this.applyError = '';
    if (job.has_quiz) {
      this.loadQuizForJob(job.id);
    } else {
      this.jobQuiz = null;
      this.quizAnswers = {};
    }
    this.cdr.detectChanges();
  }

  onCloseModal() {
    this.selectedJob = null;
    this.jobQuiz = null;
    this.quizAnswers = {};
    this.applyError = '';
    this.cdr.detectChanges();
  }

  onOpenApplyModal(job: any) {
    const token = localStorage.getItem('token');
    if (!token) {
      this.showAuthRequiredPopup = true;
      this.cdr.detectChanges();
      return;
    }

    if (job.has_quiz) {
      this.onViewJobDetails(job);
      return;
    }

    this.jobToApply = job;
    this.showConfirmApplyPopup = true;
    this.cdr.detectChanges();
  }

  goToLogin() {
    this.showAuthRequiredPopup = false;
    this.router.navigate(['/login']);
  }

  onQuizAnswerChange(event: { questionId: number; choiceId: number }) {
    this.quizAnswers[event.questionId] = event.choiceId;
    this.cdr.detectChanges();
  }

  private buildQuizAnswers(): QuizAnswerPayload[] {
    return Object.entries(this.quizAnswers).map(([questionId, choiceId]) => ({
      question_id: Number(questionId),
      choice_id: Number(choiceId),
    }));
  }

  canSubmitApply(): boolean {
    const job = this.selectedJob || this.jobToApply;
    if (!job) return false;
    if (!job.has_quiz || !this.jobQuiz?.questions?.length) return true;
    return this.jobQuiz.questions.every((q: any) => this.quizAnswers[q.id]);
  }

  onRequestApplyConfirmation() {
    const token = localStorage.getItem('token');
    if (!token) {
      this.showAuthRequiredPopup = true;
      this.cdr.detectChanges();
      return;
    }

    const job = this.selectedJob || this.jobToApply;
    if (!job) return;

    if (!this.canSubmitApply()) {
      this.applyError = 'Veuillez répondre à toutes les questions du quiz.';
      this.cdr.detectChanges();
      return;
    }

    this.jobToApply = job;
    this.applyError = '';
    this.applyPopupSuccess = false;
    this.showConfirmApplyPopup = true;
    this.cdr.detectChanges();
  }

  onCancelApplyConfirmation() {
    this.showConfirmApplyPopup = false;
    this.applyPopupSuccess = false;
    this.applyError = '';
    if (!this.selectedJob) {
      this.jobToApply = null;
    }
    this.cdr.detectChanges();
  }

  executeApplySubmit() {
    const job = this.selectedJob || this.jobToApply;
    if (!job || !this.canSubmitApply()) {
      this.applyError = 'Veuillez répondre à toutes les questions du quiz.';
      this.cdr.detectChanges();
      return;
    }

    this.isSubmitting = true;
    this.applyError = '';
    const answers = job.has_quiz ? this.buildQuizAnswers() : [];

    this.applicationService.applyToJob(job.id, answers).subscribe({
      next: () => {
        job.isAlreadyApplied = true;
        const inList = this.allJobs.find((j) => j.id === job.id);
        if (inList) inList.isAlreadyApplied = true;
        this.isSubmitting = false;
        this.applyPopupSuccess = true;
        this.cdr.detectChanges();
        setTimeout(() => {
          this.showConfirmApplyPopup = false;
          this.applyPopupSuccess = false;
          this.jobToApply = null;
          this.onCloseModal();
          this.cdr.detectChanges();
        }, 2200);
      },
      error: (err) => {
        this.isSubmitting = false;
        this.applyError = err.error?.message || 'Erreur lors de la transmission.';
        this.cdr.detectChanges();
      },
    });
  }
}
<div class="job-search-container">
  
  <!-- 🔍 ZONE SUPÉRIEURE : RECHERCHE AVANCÉE -->
  <div class="search-advanced-card">
    <div class="advanced-search-grid">
      <div class="search-filter-group">
        <label><i class="bi bi-briefcase"></i> Titre du poste</label>
        <div class="input-with-icon"><i class="bi bi-search"></i><input type="text" [(ngModel)]="searchFilters.title" placeholder="Ex: Angular..."></div>
      </div>
      <div class="search-filter-group">
        <label><i class="bi bi-geo-alt"></i> Ville / Région</label>
        <div class="input-with-icon"><i class="bi bi-map"></i><input type="text" [(ngModel)]="searchFilters.location" placeholder="Ex: Tunis..."></div>
      </div>
      <div class="search-filter-group">
        <label><i class="bi bi-mortarboard"></i> Expérience</label>
        <select [(ngModel)]="searchFilters.experience" class="select-filter-compact">
          <option value="">Tous les niveaux</option>
          <option value="Junior (0-2 ans)">Junior (0-2 ans)</option>
          <option value="Intermédiaire (2-5 ans)">Intermédiaire (2-5 ans)</option>
          <option value="Senior (5+ ans)">Senior (5+ ans)</option>
        </select>
      </div>
      <div class="search-filter-group">
        <label><i class="bi bi-tags"></i> Contrat</label>
        <select [(ngModel)]="searchFilters.contract" class="select-filter-compact">
          <option value="">Tous les contrats</option>
          <option value="CDI">CDI</option>
          <option value="CDD">CDD</option>
          <option value="SIVP">SIVP</option>
        </select>
      </div>
    </div>
    @if (hasActiveFilters) {
      <div class="reset-filters-row"><button type="button" class="btn-reset-filters" (click)="onResetFilters()"><i class="bi bi-x-circle"></i> Réinitialiser</button></div>
    }
  </div>

  <!-- ⏳ CHARGEMENT -->
  @if (isLoading) {
    <div class="loading-state-box"><i class="bi bi-arrow-clockwise spin-animation"></i><p>Chargement...</p></div>
  }

  <!-- 🚀 GRILLE DES CARTES (3 PAR LIGNE) -->
  @if (!isLoading && filteredJobs.length > 0) {
    <div class="jobs-cards-grid-3" [class.logged-in-grid]="isLoggedIn">
      @for (job of filteredJobs; track job.id) {
        <div class="job-feed-card">
          <div class="card-top-info">
            <div class="company-logo-placeholder">
              @if (job.company_logo) {
                <img [src]="environment.assetsUrl + '/logos/' + job.company_logo" alt="Logo">
              } @else {
                <i class="bi bi-building"></i>
              }
            </div>
            <div class="job-title-block">
              <h4 class="feed-job-title">{{ job.title }}</h4>
              <!-- 🌟 REND LE NOM CLIQUABLE POUR APPRENDRE PLUS SUR L'ENTREPRISE -->
              <span class="feed-company-name clickable-recruiter" (click)="onViewRecruiterProfile(job.recruiter_id)">
                <i class="bi bi-building-check"></i> {{ job.company_name || 'Entreprise Partenaire' }}
              </span>
            </div>
            <div style="display: flex; flex-direction: column; gap: 6px; align-items: flex-end;">
              <span class="contract-badge-feed">{{ job.contract_type }}</span>
              @if (job.has_quiz) {
                <span style="font-size: 10px; font-weight: 700; color: #7c3aed; background: #f3e8ff; padding: 3px 8px; border-radius: 6px;">
                  <i class="bi bi-patch-question"></i> Quiz
                </span>
              }
            </div>
          </div>

          <div class="card-mid-meta">
            <span class="meta-item"><i class="bi bi-geo-alt-fill"></i> {{ job.location }}</span>
            <span class="meta-item"><i class="bi bi-laptop-fill"></i> {{ job.workplace_type }}</span>
            <span class="meta-item"><i class="bi bi-mortarboard-fill"></i> {{ job.experience_level }}</span>
          </div>
          <p class="job-short-desc">{{ job.missions_desc | slice:0:100 }}...</p>

          <div class="card-bottom-actions">
            <button class="btn-consult-job" (click)="onViewJobDetails(job)"><i class="bi bi-eye-fill"></i> Consulter</button>
            @if (job.isAlreadyApplied) {
              <span class="badge-already-applied"><i class="bi bi-check-circle-fill"></i> Déjà postulé</span>
            } @else {
              <button class="btn-apply-now" (click)="onOpenApplyModal(job)">Postuler <i class="bi bi-arrow-right-short"></i></button>
            }
          </div>
        </div>
      }
    </div>
  }

  <!-- 👁️ MODALE 1 : DETAILS DU POSTE (INTEGRATION DU LOGO ALIGNÉ) -->
    <!-- 👁️ MODALE 1 : DETAILS DU POSTE (DESIGN PREMIUM UNIFIÉ) -->
     @if (selectedJob) {
    <div class="modal-overlay" (click)="onCloseModal()">
      <div class="modal-card" (click)="$event.stopPropagation()">
        
        <!-- En-tête fixe -->
        <div class="modal-header">
          <h3><i class="bi bi-file-earmark-text-fill"></i> Détails de l'offre d'emploi</h3>
          <button (click)="onCloseModal()" class="btn-close-modal"><i class="bi bi-x-lg"></i></button>
        </div>

        <!-- Corps de la modale organisé -->
        <div class="modal-body">
          
          <!-- Section Héro : Aligne le Logo à gauche et les infos clés sous forme de badges modernes -->
          <div class="job-hero-section">
            <div class="job-logo-wrapper">
              <img [src]="selectedJob.company_logo ? environment.assetsUrl + '/logos/' + selectedJob.company_logo : 'assets/images/default-avatar.png'" 
                   (error)="$any($event.target).src='assets/images/default-avatar.png'"
                   alt="Logo entreprise">
            </div>
            
            <div class="job-meta-content">
              <h4 class="job-main-title">{{ selectedJob.title }}</h4>
              <span class="job-company-link" (click)="onViewRecruiterProfile(selectedJob.recruiter_id)">
                <i class="bi bi-building"></i> {{ selectedJob.company_name || 'Entreprise Partenaire' }}
              </span>
              
              <!-- Ligne de badges aérés -->
              <div class="job-badges-row">
                <span class="premium-badge badge-contract"><i class="bi bi-file-earmark-text"></i> {{ selectedJob.contract_type }}</span>
                <span class="premium-badge badge-location"><i class="bi bi-geo-alt-fill"></i> {{ selectedJob.location }}</span>
                
                <!-- 📅 BADGE EXCLUSIF : DATE LIMITE D'EXPIRATION DU POSTE -->
                @if (selectedJob.expires_at) {
                  <span class="premium-badge badge-expiration" style="background-color: #fff7ed; color: #c2410c; border-color: #ffedd5; font-weight: 600;">
                    <i class="bi bi-calendar-x-fill" style="color: #ea580c;"></i> Expire le : {{ selectedJob.expires_at | date:'dd/MM/yyyy' }}
                  </span>
                }
              </div>
            </div>
          </div>

          <!-- Section 1 : Missions Principales -->
          <div class="job-text-block-section">
            <span class="job-block-title"><i class="bi bi-list-task"></i> Missions principales</span>
            <div class="job-block-card">
              <p style="white-space: pre-line; margin: 0; line-height: 1.65; color: #334155;">{{ selectedJob.missions_desc }}</p>
            </div>
          </div>

          <!-- Section 2 : Profil Requis -->
          <div class="job-text-block-section">
            <span class="job-block-title"><i class="bi bi-person-badge-fill"></i> Profil requis & Prérequis</span>
            <div class="job-block-card">
              <p style="white-space: pre-line; margin: 0; line-height: 1.65; color: #334155;">{{ selectedJob.profile_desc }}</p>
            </div>
          </div>

          <!-- Section 3 : Compétences clés & Technologies -->
          @if (selectedJob.skills_desc) {
            <div class="job-text-block-section">
              <span class="job-block-title"><i class="bi bi-tags-fill"></i> Compétences clés & Technologies</span>
              <div class="job-block-card">
                <div class="skills-badge-grid">
                  @for (skill of getSearchJobSkillsArray(selectedJob.skills_desc); track $index) {
                    <span class="skill-tag">
                      <i class="bi bi-check2"></i> {{ skill }}
                    </span>
                  }
                </div>
              </div>
            </div>
          }

          <!-- Section 4 : Langues exigées -->
          @if (selectedJob.languages_desc) {
            <div class="job-text-block-section">
              <span class="job-block-title"><i class="bi bi-translate"></i> Langues exigées</span>
              <div class="job-block-card">
                <div class="skills-badge-grid">
                  @for (lang of getSearchJobLanguagesArray(selectedJob.languages_desc); track $index) {
                    <span class="skill-tag" style="background-color: #faf5ff; color: #6b21a8; border-color: #f3e8ff;">
                      <i class="bi bi-globe"></i> {{ lang }}
                    </span>
                  }
                </div>
              </div>
            </div>
          }

          <!-- Section 5 : Quiz de présélection (carte pro) -->
          @if (selectedJob.has_quiz) {
            <div class="job-text-block-section">
              <span class="job-block-title"><i class="bi bi-patch-question-fill"></i> Questionnaire de présélection</span>
              <app-quiz-player
                [quiz]="jobQuiz"
                [loading]="isLoadingQuiz"
                [answers]="quizAnswers"
                (answerChange)="onQuizAnswerChange($event)"
              />
            </div>
          }

          @if (applyError) {
            <p style="color: #ef4444; font-size: 13px; margin: 0 0 12px;">{{ applyError }}</p>
          }

          <!-- Pied de page avec bouton d'action principal -->
          <div class="modal-footer-action-row">
            @if (selectedJob.isAlreadyApplied) {
              <span class="premium-applied-banner"><i class="bi bi-check-circle-fill"></i> Vous avez déjà postulé à cette offre</span>
            } @else {
              <button
                class="btn-submit-apply-large"
                (click)="onRequestApplyConfirmation()"
                [disabled]="!canSubmitApply() || isSubmitting"
                [style.opacity]="canSubmitApply() ? '1' : '0.55'"
              >
                @if (isSubmitting) {
                  Envoi en cours…
                } @else if (selectedJob.has_quiz && !canSubmitApply()) {
                  Complétez le quiz pour postuler
                } @else {
                  Envoyer ma candidature <i class="bi bi-arrow-right-short"></i>
                }
              </button>
            }
          </div>
          
        </div>
      </div>
    </div>
  }
  <!-- 🏢 🌟 MODALE 2 : FICHE DU RECRUTEUR EN LIGNE (D'origine, inchangée) -->
  @if (selectedRecruiter) {
    <div class="modal-overlay">
      <div class="modal-card recruiter-profile-card">
        <div class="modal-header">
          <h3><i class="bi bi-building-fill"></i> Fiche de l'entreprise</h3>
          <button (click)="onCloseRecruiterModal()" class="btn-close-modal"><i class="bi bi-x-lg"></i></button>
        </div>
        <div class="modal-body">
          <div class="recruiter-meta-header">
            <div class="large-avatar-placeholder">
              @if (selectedRecruiter.company_logo) {
                <img [src]="environment.assetsUrl + '/logos/' + selectedRecruiter.company_logo" alt="Logo">
              } @else {
                <i class="bi bi-building" style="font-size: 32px; color: #cbd5e1;"></i>
              }
            </div>
            <div class="recruiter-main-titles">
              <h4>{{ selectedRecruiter.company_name }}</h4>
              <span class="badge-verified"><i class="bi bi-patch-check-fill"></i> Partenaire Verified</span>
            </div>
          </div>

          <div class="recruiter-contact-grid">
            <div class="contact-item"><strong><i class="bi bi-envelope-fill"></i> Email :</strong> <span>{{ selectedRecruiter.email || 'Non spécifié' }}</span></div>
            <div class="contact-item"><strong><i class="bi bi-telephone-fill"></i> Téléphone :</strong> <span>{{ selectedRecruiter.phone || 'Non spécifié' }}</span></div>
            <div class="contact-item span-two"><strong><i class="bi bi-geo-alt-fill"></i> Siège social :</strong> <span>{{ selectedRecruiter.address || 'Non spécifié' }}</span></div>
          </div>

          <div class="detail-block" style="margin-top: 15px;">
            <strong>À propos de l'entreprise :</strong>
            <p class="bio-text-box">{{ selectedRecruiter.company_bio || 'Aucune description fournie par l\'entreprise.' }}</p>
          </div>
        </div>
      </div>
    </div>
  }

</div>

  <!-- 🎛️ UNIQUE POP-UP DE CONFIRMATION DE CANDIDATURE EN SURIMPRESSION -->
  @if (showConfirmApplyPopup) {
    <div class="modal-overlay" style="z-index: 100005;" (click)="onCancelApplyConfirmation()">
      <div class="modal-card" (click)="$event.stopPropagation()" style="max-width: 440px; padding: 28px; text-align: center; display: flex; flex-direction: column; gap: 16px;">
        @if (applyPopupSuccess) {
          <div style="font-size: 42px; margin-bottom: 4px;">✅</div>
          <h4 style="margin: 0; font-size: 17px; font-weight: 700; color: #166534;">Candidature envoyée !</h4>
          <p style="margin: 0; font-size: 13.5px; color: #64748b; line-height: 1.6;">
            Votre profil a bien été transmis pour l'offre :<br>
            <strong style="color: #0ea5e9;">{{ jobToApply?.title }}</strong>
          </p>
        } @else {
          <div style="font-size: 42px; margin-bottom: 4px;">🚀</div>
          <h4 style="margin: 0; font-size: 17px; font-weight: 700; color: #0f172a;">Confirmer votre candidature</h4>
          <p style="margin: 0; font-size: 13.5px; color: #64748b; line-height: 1.6;">
            Souhaitez-vous transmettre votre profil TunJob pour l'offre : <br>
            <strong style="color: #0ea5e9;">{{ jobToApply?.title }}</strong> ?
          </p>
          @if (jobToApply?.has_quiz) {
            <p style="margin: 0; font-size: 12px; color: #7c3aed; background: #f3e8ff; padding: 8px 12px; border-radius: 8px;">
              <i class="bi bi-patch-question"></i> Vos réponses au quiz seront jointes à votre candidature.
            </p>
          }

          @if (applyError) {
            <p style="color: #ef4444; font-size: 13px; margin: 0;">{{ applyError }}</p>
          }

          <div style="display: flex; gap: 12px; margin-top: 12px; width: 100%;">
            <button type="button" (click)="onCancelApplyConfirmation()" class="btn-close-modal" style="flex: 1; height: 42px; border-radius: 8px; width: 100%; font-weight: 600; font-size: 13px;">
              Annuler
            </button>
            <button type="button" (click)="executeApplySubmit()" [disabled]="!canSubmitApply() || isSubmitting" class="btn-submit-apply-large" style="flex: 1; height: 42px; border-radius: 8px; font-size: 13px;">
              @if (isSubmitting) { Envoi… } @else { Confirmer }
            </button>
          </div>
        }
      </div>
    </div>
  }
<!-- Popup Professionnelle d'Invitation à la Connexion / Inscription -->
@if (showAuthRequiredPopup) {
  <div class="custom-modal-overlay-auth" (click)="showAuthRequiredPopup = false">
    <div class="custom-modal-box-auth" (click)="$event.stopPropagation()">
      
      <div class="custom-modal-header-auth">
        <i class="bi bi-box-arrow-in-right login-icon-ats"></i>
        <h3>Connexion requise</h3>
      </div>
      
      <div class="custom-modal-body-auth">
        <p>Pour postuler à cette offre et transmettre votre dossier aux recruteurs sur <strong>TunJob Portal</strong>, vous devez posséder un compte candidat connecté.</p>
        <p class="sub-text-auth">L'inscription est gratuite et prend moins de 2 minutes !</p>
      </div>
      
      <div class="custom-modal-footer-auth">
        <button type="button" class="btn-modal-cancel-auth" (click)="showAuthRequiredPopup = false">
          Plus tard
        </button>
        <button type="button" class="btn-modal-confirm-auth" (click)="goToLogin()">
          Se connecter / S'inscrire
        </button>
      </div>

    </div>
  </div>
}
